:root {
    --main: hsl(0, 0%, 0%);
    --textColor: hsl(0, 0%, 64%);
    --sec: hsl(0, 0%, 0%);
    --accent: hsl(0, 3%, 28%);
    --sub: var(--trans);
    --check: hsl(0, 0%, 76%);
    --coins: hsl(39, 100%, 50%);
    --gem: hsl(196, 100%, 50%);
    --trans: transparent;
    --white: #fff;
    --br: 10px;
    --opacity: .7;
    --glow: 0 0 5px var(--white),
        0 0 10px var(--white),
        0 0 20px var(--accent),
        0 0 40px var(--accent);
    --progressGlow: 0 0 10px var(--accent),
        0 0 15px var(--accent),
        0 0 25px var(--accent),
        0 0 45px var(--accent);
    --background: url("https://cdn.discordapp.com/attachments/1212363198041296937/1252122876186722446/emangbolehnjir_8.gif?ex=667111cd&is=666fc04d&hm=c7a2b0c10705c81502bc200cb40df133e047a72ba235d32bf26271bd384c44c6&");
    --php: url("https://cdn.discordapp.com/attachments/1206197908399980575/1252408462856683680/a_994f00f6f65945adca05044da2e951c8.gif?ex=66721bc6&is=6670ca46&hm=97f18ec6ff6cb8a9e43bc3e60107bad74c4966f288083aba146573280577abd8&")
}

/* scroll bar */

