    font-size: 0 !important;
}

/* Hub */

.info-awards {
    background: var(--sec) !important;
    box-shadow: none !important;
    border-radius: 0 var(--br) 0 0 !important;
    padding: 0.7rem 2rem 0.7rem 1rem !important;
}

div.content {
  background: var(--trans)!important;
}

div.hub-container {
  background: var(--trans);
}

.awards-span {
    font-weight: 800 !important;
    color: var(--accent) !important;
}

.info-awards .reset {
    font-weight: 700 !important;
    text-shadow: var(--glow);
}

.leaders>.head-leaders>.head>.cont-name {
    margin-bottom: 10px !important;
}

.list-cont {
    background: var(--trans) !important;
    box-shadow: none !important;
    border-radius: 5px !important;
}

.top-items {
    background: var(--trans) !important;
    box-shadow: none !important;
    padding-bottom: 0 !important;
    height: 11.5rem !important;
}

.top-label {
    text-shadow: var(--glow);
}

.list-champions {
    bottom: 80px !important;
}

.item {
    background-color: var(--sec) !important;
    border-radius: 5px !important;
}

.number-player {
    color: var(--accent) !important;
}

.top-items>.items>.item>.left>.number-player {
    color: var(--white) !important;
    text-shadow: var(--glow);
}

.bottom-items::-webkit-scrollbar {
    background-color: var(--trans) !important;
}

.bottom-items::-webkit-scrollbar-thumb {
    background-color: var(--trans) !important;
}

.bottom-items {
    width: calc(100% + 1%) !important;
    height: calc(100% - 9.5rem) !important;
}

.list-champions .value {
    font-weight: 800 !important;
}

.list-champions .svg-icon {
    margin-left: 10px;
}

.svg-icon--star {
    content: "";
    background: var(--accent) !important;
    height: 11px !important;
    width: 11px !important;
    transform: rotate(45deg);
    border-radius: 0.025rem;
    filter: brightness(1.3);
    visibility: visible !important;
}

/* clans */

.clans .nav {
    padding: 10px;
    background-color: var(--sec) !important;
    margin-bottom: -15px;
    border-radius: 5px;
    font-weight: 900;
}

.active, .nav:hover {
    color: currentColor !important;
}

.reset-time {
    background: var(--sec) !important;
    top: unset !important;
    bottom: 45px !important;
    width: 20rem !important;
    height: 5rem !important;
    background: var(--sec) !important;
    box-shadow: none !important;
    border-radius: var(--br) 0 0 0 !important;
    padding: 0.7rem 2rem 0.7rem 1rem !important;
    align-items: flex-end !important;
    font-weight: 700 !important;
    text-shadow: var(--glow);
    font-size: 20px;
}

.reset-time::after {
    content: "Awards";
    position: absolute;
    top: 10px;
    font-weight: 800;
    color: var(--accent);
    font-size: 1.5rem !important;
    text-shadow: none !important;
    text-transform: uppercase;
}

.reset-time::before {
    content: "Of The Month";
    position: absolute;
    top: 10px;
    left: 114px;
    font-size: 1.5rem;
    text-shadow: none !important;
    font-weight: 800;
}

.clans {
    background: var(--main) !important;
}

/* HUD */
.mini-map-cont .name,
.desktop-game-interface .info-key-cont,
.list-weapons,
.hp-title,
.mWwn,
.instruction {
    display: none !important;
}

.cont-hp {
    background: transparent !important;
}

.hp {
    margin-right: 20%;
}

.hp-progress {
     background: -webkit-gradient(linear, left top, right top, from var(--white), to var(--main)) !important;
    background: linear-gradient(to right, var(--sec), var(--white)) !important;
}

.desktop-game-interface .state {
    position: fixed;
    width: 500px !important;
    top: 93%;
    left: 0.5% !important;
}

.cont-endurance {
    margin-left: 1.5%;
    background: transparent !important;
}

.endurance-progress {
	background: -webkit-gradient(linear, left top, right top, from var(--check), to var(--accent)) !important;
    background: linear-gradient(to right, var(--accent), var(--check)) !important;
}

.ammunition {
    display: inline-block;
    position: fixed;
    top: 87%;
    left: 490px;
}

.kill-death {
    margin-top: 60px;
    margin-left: 2px;
}

.kill-death .kill,
.kill-death .death {
    background: rgba(255, 203, 0, 0);
    box-shadow: none;
}

.state-cont .timer {
    color: var(--gem);
    position: fixed;
    top: 18px;
    background: transparent !important;
    box-shadow: none !important;
    font-size: 35px;
}

.chat {
    margin-bottom: -5px;
    border-radius: 5px;
    /*-webkit-mask-image: linear-gradient(to bottom, transparent, black, black);*/
}

.chat .input-wrapper {
    top: 400px !important;
    width: 103%;
    height: 15px;
}

.chat .name {
    color: var(--white);
}

.message{
    color: var(--white) !important;
}

.message .lvl {
    color: var(--white);
}

/* Clan */
.clans,
.clans .items .item,
.my-clan .list-container .list .item .item-content {
   background: var(--bgClan) !important;
       -webkit-animation: glow 2s ease-in-out infinite alternate;
}

.my-clan .card-cont,
.my-clan .list-container,
.champions-list {
   background: transparent !important;
   box-shadow: none !important;
}

.my-clan .card-cont .name {
   color: #000;
   -webkit-animation: glow 2s ease-in-out infinite alternate;
   -moz-animation: glow 2s ease-in-out infinite alternate;
   animation: glow 2s ease-in-out infinite alternate;
}

.my-clan .champions-league,
.my-clan .champions-scores,
.my-clan .all-scores-label {
   color: #fff !important;
}

.my-clan .champions-values,
.my-clan .all-scores-value,
.my-clan .description {
   color: #fff;
}